void CBrowserView::OnSize(UINT, int cx, int cy)
{
    CSize size(0, 0);
    if (toolBar.GetSafeHwnd()) {
        size = toolBar.CalcDockingLayout(cx, LM_STRETCH | LM_HORZ | LM_HORZDOCK | LM_COMMIT | LM_HIDEWRAP);
        toolBar.MoveWindow(0, 0, cx, size.cy);
