{
    CSecureHtmlView::OnNavigateComplete2(url);
    if (addressCombo) {
        bool unvisited = std::find(history.begin(), history.end(), std::string(url)) == history.end();
        if (unvisited) {
            CString text(url);
            addressCombo->SetEditText(text);
        }
    }
}

